// Scratch probe for ENG-2228 kit authoring: drives testVault2 over CDP.
const list = await (await fetch("http://127.0.0.1:9222/json/list")).json();
let ws, id = 0; const pending = new Map();
const send = (method, params = {}) => new Promise((res, rej) => { const n = ++id; pending.set(n, { res, rej }); ws.send(JSON.stringify({ id: n, method, params })); });
const ev = async (js) => { const r = await send("Runtime.evaluate", { expression: `Promise.resolve((0,eval)(${JSON.stringify(js)}))`, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? r.exceptionDetails.text); return r.result.value; };
for (const t of list.filter((t) => t.type === "page")) {
  ws = new WebSocket(t.webSocketDebuggerUrl); await new Promise((r) => ws.addEventListener("open", r, { once: true }));
  ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); const p = pending.get(m.id); if (p) { pending.delete(m.id); m.error ? p.rej(new Error(m.error.message)) : p.res(m.result); } });
  if (await ev(`app?.vault?.adapter?.basePath?.endsWith("testVault2") ?? false`)) break; ws.close(); ws = null;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const mouse = (type, x, y, extra = {}) => send("Input.dispatchMouseEvent", { type, x, y, ...extra });
const click = async (x, y, button = "left") => { await mouse("mouseMoved", x, y); await mouse("mousePressed", x, y, { button, buttons: button === "left" ? 1 : 2, clickCount: 1 }); await mouse("mouseReleased", x, y, { button, buttons: 0, clickCount: 1 }); };
const key = async (k, code, vk, text) => { await send("Input.dispatchKeyEvent", { type: text ? "keyDown" : "rawKeyDown", key: k, code, windowsVirtualKeyCode: vk, ...(text ? { text } : {}) }); await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code, windowsVirtualKeyCode: vk }); };
await send("Emulation.setFocusEmulationEnabled", { enabled: true });
const step = process.argv[2];
const EDITOR = `(() => { const c = app.workspace.activeLeaf.view.containerEl.querySelector(".tl-canvas"); if (!c) return null; let f = c[Object.keys(c).find((k) => k.startsWith("__reactFiber$"))]; while (f && !f.memoizedProps?.value?.putExternalContent) f = f.return; return f?.memoizedProps?.value ?? null; })()`;
if (step === "canvas") {
  await ev(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); app.commands.executeCommandById(Object.values(app.commands.commands).find((c) => c.name.endsWith("Create new Discourse Graph canvas")).id)`);
  await sleep(2500);
  console.log(await ev(`({ file: app.workspace.getActiveFile()?.path, canvas: !!app.workspace.activeLeaf.view.containerEl.querySelector(".tl-canvas"), editor: !!${EDITOR} })`));
}
if (step === "text") {
  const box = await ev(`(() => { const r = app.workspace.activeLeaf.view.containerEl.querySelector(".tl-canvas").getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
  await key("t", "KeyT", 84, "t"); await sleep(200); await click(box.x, box.y); await sleep(300);
  await send("Input.insertText", { text: "pk 2228 linked text" }); await sleep(200); await key("Escape", "Escape", 27); await sleep(700);
  console.log(await ev(`(() => { const e = ${EDITOR}; return e.getCurrentPageShapes().map((s) => ({ id: s.id, type: s.type, meta: s.meta })); })()`));
}
if (step === "menu") {
  const at = await ev(`(() => { const e = ${EDITOR}; const s = e.getCurrentPageShapes().find((s) => s.type === "text"); e.select(s.id); const b = e.getShapePageBounds(s.id); const p = e.pageToViewport(b.center); const r = app.workspace.activeLeaf.view.containerEl.querySelector(".tl-canvas").getBoundingClientRect(); return { x: p.x + r.left, y: p.y + r.top }; })()`);
  await click(at.x, at.y, "right"); await sleep(500);
  console.log(await ev(`[...document.querySelectorAll(".tlui-menu [data-testid]")].map((n) => n.dataset.testid + " | " + n.textContent.trim()).join("\\n")`));
}
if (step === "eval") console.log(await ev(process.argv[3]));
ws.close();
EOF
