        step({"wait_for": TEXT}, "the text shape is on the canvas"),
    ]

HELPERS = r"""(() => {
  const leafEl = () => app.workspace.activeLeaf.view.containerEl;
  const editor = () => {
    const canvas = leafEl().querySelector('.tl-canvas');
    if (!canvas) throw new Error('The active tab is not the kit canvas.');
    let fiber = canvas[Object.keys(canvas).find((key) => key.startsWith('__reactFiber$'))];
    while (fiber && !(fiber.memoizedProps && fiber.memoizedProps.value && fiber.memoizedProps.value.putExternalContent)) fiber = fiber.return;
    if (!fiber) throw new Error('No tldraw editor under the canvas.');
    return fiber.memoizedProps.value;
  };
  const shapes = (type) => editor().getCurrentPageShapes().filter((shape) => shape.type === type);
  window.pk2228 = {
    editor,
    text: () => shapes('text')[0] || null,
    geo: () => shapes('geo')[0] || null,
    textUrl: () => { const shape = shapes('text')[0]; return (shape && shape.meta && shape.meta.url) || ''; },
    textTool: () => { editor().setCurrentTool('text'); return true; },
    openCanvas: async () => {
      await proof.obsidian.closeModals();
      await app.workspace.getLeaf(false).openFile(app.vault.getAbstractFileByPath(window.pk2228.canvasPath));
      await proof.waitFor(() => leafEl().querySelector('.tl-canvas') && editor(), { what: 'the kit canvas' });
      return true;
