// What an agent is told when the panel asks for one: which kit, and the
// runner's tools it drives the kit through.
export const agentPrompt = (graph: string, uid: string): string =>
  [
    `You're the agent for a proof kit open in Roam: graph ${graph}, the {{proof}} block ((${uid})).`,
    "Drive it through the proof runner's tools on Roam's MCP: proof_status first, proof_snapshot for the page's",
    "elements, proof_add_steps for a case waiting for steps, proof_fix_step for a failed step, and proof_control",
    "to run, pause, retry or skip. Prefer the command palette, clicks and typing over js: js waits for sid's",
    "Allow in the panel, and verdicts are his. How steps are written: /mnt/data/projects/dg-demo-videos/proof/README.md",
    "('The page' and 'The brain's loop'); recipes are in /mnt/data/projects/dg-demo-videos/proof/recipes.",
  ].join(" ");

## Agent tools

With Roam's AI API (`extensionAPI.ai.addTool`), the runner registers tools an agent connected to the
graph can call: `proof_status`, `proof_snapshot`, `proof_control`, `proof_add_steps` and
`proof_fix_step`. An agent can read a kit and its run, see the page's dialogs and controls, run and
pause, write steps for a by-hand case onto the page, and fix a failed step. Js an agent writes waits
for an Allow in the panel, and verdicts stay with the person. The checklist's **Ask your agent**
opens a `dg-proof://agent` link that starts one. From `roam/js` there is no `extensionAPI`, so no
tools.

Kit pages run their own js when you press Run, so keep kits in graphs shared with people you trust,
as with `roam/js`.
import type { ExtensionAPI } from "./build-loader";
import { controlsOnPage, snapshotPage } from "./executor";
import type { ProofRun } from "./runner";

// The runner's tools for an agent connected to Roam: Roam's AI API
// (extensionAPI.ai.addTool) hands tools an extension registers to agents
// that reach the graph through a Local API token (Roam's MCP). Through
// them an agent reads a kit and its run, sees the page, controls the run,
// and writes steps onto the page. Verdicts and allowing js stay with the
// person at the panel. A Roam without the API registers nothing.

